def compute(vars):
    snap_on = vars["v1"]
    peer_group = vars["v2"]

    if peer_group == 0:
        return None

    value = snap_on / peer_group
    return {
        "value": value,
        "trace": {
            "snap_on": snap_on,
            "peer_group": peer_group,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
